S=/private/tmp/claude-501/-Users-serro-Documents-dev-n-agent-experiments-skillplane/ca62123f-e191-43ba-a12e-6d1b29e43d5c/scratchpad/pr46; mkdir -p $S; cd $S
GH_CONFIG_DIR=~/.config/gh-other gh api graphql --paginate -f query='
query($endCursor: String) {
  repository(owner: "21nCo", name: "skillplane") {
    pullRequest(number: 46) {
      headRefOid
      reviewThreads(first: 100, after: $endCursor) {
        nodes { id isResolved isOutdated path line
          comments(first: 50) { nodes { body author { login } createdAt outdated url line originalLine } pageInfo { hasNextPage endCursor } }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}' > threads.json
python3 - <<'EOF'
import json
txt=open('threads.json').read()
# paginate may concatenate objects
dec=json.JSONDecoder();i=0;objs=[]
while i<len(txt):
  txt2=txt[i:].lstrip()
  if not txt2:break
  o,n=dec.raw_decode(txt2);objs.append(o);i=len(txt)-len(txt2)+n
th=[]
for o in objs:
  pr=o['data']['repository']['pullRequest'];print('head',pr['headRefOid'])
  th+=pr['reviewThreads']['nodes']
print('total',len(th),'unresolved',sum(not t['isResolved'] for t in th))
for t in th:
  if t['comments']['pageInfo']['hasNextPage']: print('NESTED PAGE',t['id'])
json.dump(th,open('th.json','w'))
for k,t in enumerate(th):
  if t['isResolved']: continue
  c=t['comments']['nodes']
  print(f"\n### [{k}] {t['id']} {t['path']}:{t['line']} outdated={t['isOutdated']} n={len(c)}")
  for x in c: print(f"-- {x['author']['login']} {x['createdAt']} {x['url']}\n{x['body'][:1800]}")
EOF

