content.content:
  1	<script lang="ts">
  2	  import { resolve } from "$app/paths";
  3	  import { SvelteURLSearchParams } from "svelte/reactivity";
  4	  import { page } from "$app/state";
  5	  import { Button, Input, Select, EmptyState } from "@skillplane/ui";
  6	  import { apiRequest } from "$lib/api/client.js";
  7	  import { groupRequest, type Group, type Member } from "$lib/groups/api.js";
  8	  import { useWorkspaceStore } from "$lib/workspaces/store.svelte.js";
  9	  import type { Skill } from "$lib/skills/types.js";
 10	  const store = useWorkspaceStore();
 11	  const workspace = $derived(
 12	    store.workspaces.find((w) => w.slug === page.params.workspaceSlug) ?? null,
 13	  );
 14	  const canManage = $derived(
 15	    workspace?.role === "admin" || workspace?.role === "owner",
 16	  );
 17	  let groups = $state<Group[]>([]),
 18	    selected = $state<Group | null>(null),
 19	    name = $state(""),
 20	    description = $state(""),
 21	    includeArchived = $state(false),
 22	    busy = $state(false),
 23	    error = $state(""),
 24	    loaded = $state("");
 25	  let groupCursor = $state<string | null>(null),
 26	    skills = $state<
 27	      (Pick<Skill, "id" | "name" | "slug"> & { archivedAt: string | null })[]
 28	    >([]),
 29	    skillCursor = $state<string | null>(null),
 30	    members = $state<Member[]>([]),
 31	    memberCursor = $state<string | null>(null),
 32	    roster = $state<Member[]>([]),
 33	    available = $state<Skill[]>([]),
 34	    targetSkill = $state(""),
 35	    targetMember = $state(""),
 36	    query = $state("");
 37	  function isCurrent(workspaceId: string, groupId?: string) {
 38	    return (
 39	      workspace?.id === workspaceId &&
 40	      (groupId === undefined || selected?.id === groupId)
 41	    );
 42	  }
 43	  let creationKey = crypto.randomUUID();
 44	  let listGeneration = 0,
 45	    listLoaded = $state(false),
 46	    listLoading = $state(false);
 47	  async function load(more = false) {
 48	    if (!workspace) return;
 49	    const workspaceId = workspace.id,
 50	      memberId = page.url.searchParams.get("memberId") ?? "",
 51	      archived = includeArchived,
 52	      generation = ++listGeneration;
 53	    if (!more) {
 54	      groupCursor = null;
 55	      listLoaded = false;
 56	    }
 57	    listLoading = true;
 58	    try {
 59	      const result = await groupRequest<{ groups: Group[]; nextCursor: string | null }>(
 60	        workspaceId,
 61	        `?${memberId ? `userId=${encodeURIComponent(memberId)}&` : ""}state=${archived ? "all" : "active"}${more && groupCursor ? `&cursor=${encodeURIComponent(groupCursor)}` : ""}`,
 62	      );
 63	      if (
 64	        !isCurrent(workspaceId) ||
 65	        memberId !== (page.url.searchParams.get("memberId") ?? "") ||
 66	        archived !== includeArchived ||
 67	        generation !== listGeneration
 68	      )
 69	        return;
 70	      groups = more ? [...groups, ...result.groups] : result.groups;
 71	      groupCursor = result.nextCursor;
 72	      listLoaded = true;
 73	    } finally {
 74	      if (generation === listGeneration) listLoading = false;
 75	    }
 76	  }
 77	  async function detail(group: Group) {
 78	    if (!workspace) return;
 79	    const workspaceId = workspace.id;
 80	    selected = group;
 81	    targetMember = "";
 82	    targetSkill = "";
 83	    name = group.name;
 84	    description = group.description;
 85	    skills = [];
 86	    members = [];
 87	    skillCursor = null;
 88	    memberCursor = null;
 89	    await Promise.all([loadSkills(), loadMembers()]);
 90	    if (canManage) {
 91	      const r = await apiRequest<{ members: Member[] }>(
 92	        `/api/v1/workspaces/${encodeURIComponent(workspace.id)}/members`,
 93	      );
 94	      if (!isCurrent(workspaceId, group.id)) return;
 95	      roster = r.members;
 96	      await searchSkills();
 97	    }
 98	  }
 99	  async function loadSkills(more = false) {
100	    if (!workspace || !selected) return;
101	    const workspaceId = workspace.id,
102	      groupId = selected.id;
103	    const q = new SvelteURLSearchParams({ limit: "20" });
104	    if (more && skillCursor) q.set("cursor", skillCursor);
105	    const r = await groupRequest<{
106	      skills: (Pick<Skill, "id" | "name" | "slug"> & { archivedAt: string | null })[];
107	      nextCursor: string | null;
108	    }>(workspaceId, `/${encodeURIComponent(groupId)}/skills?${q}`);
109	    if (!isCurrent(workspaceId, groupId)) return;
110	    skills = more ? [...skills, ...r.skills] : r.skills;
111	    skillCursor = r.nextCursor;
112	  }
113	  async function loadMembers(more = false) {
114	    if (!workspace || !selected) return;
115	    const workspaceId = workspace.id,
116	      groupId = selected.id;
117	    const r = await groupRequest<{ members: Member[]; nextCursor: string | null }>(
118	      workspace.id,
119	      `/${encodeURIComponent(selected.id)}/members${more && memberCursor ? `?cursor=${encodeURIComponent(memberCursor)}` : ""}`,
120	    );
121	    if (!isCurrent(workspaceId, groupId)) return;
122	    members = more ? [...members, ...r.members] : r.members;
123	    memberCursor = r.nextCursor;
124	  }
125	  async function searchSkills() {
126	    if (!workspace) return;
127	    const workspaceId = workspace.id;
128	    const r = await apiRequest<{ skills: Skill[] }>(
129	      `/api/v1/workspaces/${encodeURIComponent(workspace.id)}/skills?${new SvelteURLSearchParams({ q: query, limit: "100" })}`,
130	    );
131	    if (!isCurrent(workspaceId)) return;
132	    available = r.skills;
133	    targetSkill = "";
134	  }
135	  async function run(fn: () => Promise<void>) {
136	    if (busy || !workspace) return;
137	    const scope = loaded;
138	    busy = true;
139	    error = "";
140	    try {
141	      await fn();
142	    } catch (e) {
