  return apiRequest<T>(
    `/api/v1/workspaces/${encodeURIComponent(workspaceId)}/groups${path}`,
    {
      method,
      headers: {
        "x-skillplane-workspace-id": workspaceId,
        "idempotency-key": idempotencyKey,
      },
      ...(body === undefined ? {} : jsonBody(body)),
    },
  );
}
