  1	import type { Pool, PoolClient } from "pg";
  2	import { authorize } from "./authorization.js";
  3	import { DomainError } from "./errors.js";
  4	import type { Principal } from "./principal.js";
  5	import { insertPrincipalAudit } from "./mutation-audit.js";
  6	import { withDomainTransaction } from "./transactions.js";
  7	import { hashIdempotentRequest, validateIdempotencyKey } from "./idempotency.js";
  8	
  9	export interface SkillGroup {
 10	  id: string;
 11	  workspaceId: string;
 12	  name: string;
 13	  description: string;
 14	  revision: number;
 15	  archivedAt: string | null;
 16	  createdAt: string;
 17	  updatedAt: string;
 18	}
 19	interface GroupRow {
 20	  id: string;
 21	  workspace_id: string;
 22	  name: string;
 23	  description: string;
 24	  creation_hash: string;
 25	  revision: number;
 26	  archived_at: Date | null;
 27	  created_at: Date;
 28	  updated_at: Date;
 29	}
 30	function record(row: GroupRow): SkillGroup {
 31	  return {
 32	    id: row.id,
 33	    workspaceId: row.workspace_id,
 34	    name: row.name,
 35	    description: row.description,
 36	    revision: row.revision,
 37	    archivedAt: row.archived_at?.toISOString() ?? null,
 38	    createdAt: row.created_at.toISOString(),
 39	    updatedAt: row.updated_at.toISOString(),
 40	  };
 41	}
 42	export function groupMetadata(name: unknown, description: unknown = "") {
 43	  if (typeof name !== "string" || typeof description !== "string")
 44	    throw new DomainError(
 45	      "VALIDATION_FAILED",
 46	      "Group name and description must be text",
 47	      400,
 48	    );
 49	  const normalized = name.trim().replace(/\s+/gu, " ").normalize("NFC");
 50	  if (!normalized || normalized.length > 120 || description.length > 2000)
 51	    throw new DomainError(
 52	      "VALIDATION_FAILED",
 53	      "Use a group name of 1–120 characters and description up to 2000 characters",
 54	      400,
 55	    );
 56	  return { name: normalized, description: description.trim() };
 57	}
 58	export function groupPage(limit: unknown = 50, cursor: unknown = null) {
 59	  const n = Number(limit);
 60	  if (
 61	    !Number.isInteger(n) ||
 62	    n < 1 ||
 63	    n > 100 ||
 64	    (cursor !== null && (typeof cursor !== "string" || cursor.length > 200))
 65	  )
 66	    throw new DomainError("VALIDATION_FAILED", "Invalid group page", 400);
 67	  return { limit: n, cursor };
 68	}
 69	function writePermission(principal: Principal) {
 70	  authorize(principal, "workspace:update");
 71	}
 72	interface Mutation {
 73	  principal: Principal;
 74	  requestId: string;
 75	  fencingEpoch?: number;
 76	}
 77	export class SkillGroupService {
 78	  constructor(
 79	    private readonly pool: Pool,
 80	    private readonly controlPool: Pool = pool,
 81	  ) {}
 82	  async list(
 83	    principal: Principal,
 84	    options: {
 85	      archived?: boolean;
 86	      limit?: number;
 87	      cursor?: string | null;
 88	      skillId?: string;
 89	      userId?: string;
 90	    } = {},
 91	  ) {
 92	    authorize(principal, "skills:read");
 93	    const page = groupPage(options.limit ?? 50, options.cursor ?? null);
 94	    const result = await this.pool.query<GroupRow>(
 95	      `SELECT g.* FROM skill_groups g WHERE g.workspace_id=$1 AND ($2::boolean OR g.archived_at IS NULL) AND ($3::text IS NULL OR g.id>$3) AND ($5::text IS NULL OR EXISTS(SELECT 1 FROM skill_group_skills a WHERE a.workspace_id=g.workspace_id AND a.group_id=g.id AND a.skill_id=$5)) AND ($6::text IS NULL OR EXISTS(SELECT 1 FROM skill_group_members a WHERE a.workspace_id=g.workspace_id AND a.group_id=g.id AND a.user_id=$6)) ORDER BY g.id LIMIT $4`,
 96	      [
 97	        principal.workspaceId,
 98	        options.archived ?? false,
 99	        page.cursor,
100	        page.limit + 1,
101	        options.skillId ?? null,
102	        options.userId ?? null,
103	      ],
104	    );
105	    return {
106	      groups: result.rows.slice(0, page.limit).map(record),
107	      nextCursor:
108	        result.rows.length > page.limit
109	          ? (result.rows[page.limit - 1]?.id ?? null)
110	          : null,
111	    };
112	  }
113	  async get(principal: Principal, groupId: string) {
114	    authorize(principal, "skills:read");
115	    const r = await this.pool.query<GroupRow>(
116	      "SELECT * FROM skill_groups WHERE workspace_id=$1 AND id=$2",
117	      [principal.workspaceId, groupId],
118	    );
119	    if (!r.rows[0]) throw new DomainError("NOT_FOUND", "Group was not found", 404);
120	    return record(r.rows[0]);
121	  }
122	  async create(
123	    options: Mutation & {
124	      name: unknown;
125	      description?: unknown;
126	      idempotencyKey: string;
127	    },
128	  ) {
129	    writePermission(options.principal);
130	    const data = groupMetadata(options.name, options.description ?? "");
131	    const key = validateIdempotencyKey(options.idempotencyKey);
132	    const creationHash = await hashIdempotentRequest(data);
133	    const id = `group:${await hashIdempotentRequest({ workspaceId: options.principal.workspaceId, actor: options.principal.actorId, key })}`;
134	    return this.mutate(options, async (client) => {
135	      await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))", [id]);
136	      const existing = await client.query<GroupRow>(
137	        "SELECT * FROM skill_groups WHERE workspace_id=$1 AND id=$2",
138	        [options.principal.workspaceId, id],
139	      );
140	      if (existing.rows[0]) {
141	        const g = record(existing.rows[0]);
142	        if (existing.rows[0].creation_hash !== creationHash)
143	          throw new DomainError(
144	            "IDEMPOTENCY_KEY_REUSED",
145	            "The creation key was already used",
146	            409,
147	          );
148	        return g;
149	      }
150	      const r = await client.query<GroupRow>(
151	        "INSERT INTO skill_groups(id,workspace_id,name,description,creation_hash) VALUES($1,$2,$3,$4,$5) ON CONFLICT(id) DO NOTHING RETURNING *",
152	        [id, options.principal.workspaceId, data.name, data.description, creationHash],
153	      );
154	      if (!r.rows[0]) {
155	        const error = Object.assign(new Error("Concurrent group creation"), {
156	          code: "40001",
157	        });
158	        throw error;
159	      }
160	      await this.audit(client, options, id, "created", {});
161	      return record(r.rows[0]);
162	    });
163	  }
164	  async update(
165	    options: Mutation & {
166	      groupId: string;
167	      expectedRevision: number;
168	      name: unknown;
169	      description?: unknown;
170	      archived: boolean;
171	    },
172	  ) {
173	    writePermission(options.principal);
174	    const data = groupMetadata(options.name, options.description ?? "");
175	    if (
176	      !Number.isSafeInteger(options.expectedRevision) ||
177	      options.expectedRevision < 1 ||
178	      typeof options.archived !== "boolean"
179	    )
180	      throw new DomainError(
181	        "VALIDATION_FAILED",
182	        "A revision and archived state are required",
183	        400,
184	      );
185	    return this.mutate(options, async (client) => {
186	      await this.lock(client, options.principal, options.groupId);
187	      const r = await client.query<GroupRow>(
188	        "UPDATE skill_groups SET name=$3,description=$4,archived_at=CASE WHEN $5::boolean THEN COALESCE(archived_at,now()) ELSE NULL END,revision=revision+1,updated_at=now() WHERE workspace_id=$1 AND id=$2 AND revision=$6 RETURNING *",
189	        [
190	          options.principal.workspaceId,
191	          options.groupId,
192	          data.name,
193	          data.description,
194	          options.archived,
195	          options.expectedRevision,
196	        ],
197	      );
198	      if (!r.rows[0])
199	        throw new DomainError("CONFLICT", "Group changed; reload before saving", 409);
200	      await this.audit(client, options, options.groupId, "updated", {
201	        archived: options.archived,
202	      });
203	      return record(r.rows[0]);
204	    });
205	  }
206	  async association(
207	    options: Mutation & {
208	      groupId: string;
209	      kind: "skill" | "member";
210	      targetId: string;
211	      add: boolean;
212	    },
213	  ) {
214	    writePermission(options.principal);
215	    if (!options.targetId || options.targetId.length > 200)
216	      throw new DomainError("VALIDATION_FAILED", "A target is required", 400);
217	    if (options.kind === "member" && options.add) {
218	      const member = await this.controlPool.query(
219	        "SELECT 1 FROM workspace_memberships WHERE workspace_id=$1 AND user_id=$2",
220	        [options.principal.workspaceId, options.targetId],
221	      );
222	      if (!member.rowCount)
223	        throw new DomainError("NOT_FOUND", "Workspace member was not found", 404);
224	    }
225	    return this.mutate(options, async (client) => {
226	      const group = await this.lock(client, options.principal, options.groupId);
227	      if (group.archived_at)
228	        throw new DomainError(
229	          "CONFLICT",
230	          "Restore the group before changing assignments",
231	          409,
232	        );
233	      if (options.kind === "skill") {
234	        const r = await client.query(
235	          "SELECT 1 FROM skills WHERE workspace_id=$1 AND id=$2 FOR SHARE",
236	          [options.principal.workspaceId, options.targetId],
237	        );
238	        if (!r.rowCount)
239	          throw new DomainError("NOT_FOUND", "Workspace skill was not found", 404);
240	      }
241	      const table =
242	          options.kind === "skill" ? "skill_group_skills" : "skill_group_members",
243	        column = options.kind === "skill" ? "skill_id" : "user_id";
244	      const r = await client.query(
245	        options.add
246	          ? `INSERT INTO ${table}(workspace_id,group_id,${column}) VALUES($1,$2,$3) ON CONFLICT DO NOTHING RETURNING group_id`
247	          : `DELETE FROM ${table} WHERE workspace_id=$1 AND group_id=$2 AND ${column}=$3 RETURNING group_id`,
248	        [options.principal.workspaceId, options.groupId, options.targetId],
249	      );
250	      if (r.rowCount)
251	        await this.audit(
252	          client,
253	          options,
254	          options.groupId,
255	          `${options.kind}.${options.add ? "added" : "removed"}`,
256	          { targetId: options.targetId },
257	        );
258	      return { changed: Boolean(r.rowCount) };
259	    });
260	  }
261	  async skills(
262	    principal: Principal,
263	    groupId: string,
264	    options: { limit?: number; cursor?: string | null } = {},
265	  ) {
266	    await this.get(principal, groupId);
267	    const page = groupPage(options.limit ?? 20, options.cursor ?? null);
268	    const r = await this.pool.query<{
269	      id: string;
270	      name: string;
271	      slug: string;
272	      archived_at: Date | null;
273	    }>(
274	      "SELECT s.id,s.name,s.slug,s.archived_at FROM skill_group_skills a JOIN skills s ON s.id=a.skill_id AND s.workspace_id=a.workspace_id WHERE a.workspace_id=$1 AND a.group_id=$2 AND ($3::text IS NULL OR s.id>$3) ORDER BY s.id LIMIT $4",
275	      [principal.workspaceId, groupId, page.cursor, page.limit + 1],
276	    );
277	    return {
278	      skills: r.rows
279	        .slice(0, page.limit)
280	        .map((s) => ({
281	          id: s.id,
