  8	
  9	export interface SkillGroup {
 10	  id: string;
 11	  workspaceId: string;
 12	  name: string;
 13	  description: string;
 14	  revision: number;
 15	  archivedAt: string | null;
 16	  createdAt: string;
 17	  updatedAt: string;
 18	}
 19	interface GroupRow {
 20	  id: string;
 21	  workspace_id: string;
 22	  name: string;
 23	  description: string;
 24	  creation_hash: string;
 25	  revision: number;
 26	  archived_at: Date | null;
 27	  created_at: Date;
 28	  updated_at: Date;
 29	}
 30	function record(row: GroupRow): SkillGroup {
 31	  return {
 32	    id: row.id,
 33	    workspaceId: row.workspace_id,
 34	    name: row.name,
 35	    description: row.description,
 36	    revision: row.revision,
 37	    archivedAt: row.archived_at?.toISOString() ?? null,
 38	    createdAt: row.created_at.toISOString(),
 39	    updatedAt: row.updated_at.toISOString(),
 40	  };
 41	}
 42	export function groupMetadata(name: unknown, description: unknown = "") {
 43	  if (typeof name !== "string" || typeof description !== "string")
 44	    throw new DomainError(
 45	      "VALIDATION_FAILED",
 46	      "Group name and description must be text",
 47	      400,
 48	    );
 49	  const normalized = name.trim().replace(/\s+/gu, " ").normalize("NFC");
 50	  if (!normalized || normalized.length > 120 || description.length > 2000)
 51	    throw new DomainError(
 52	      "VALIDATION_FAILED",
 53	      "Use a group name of 1–120 characters and description up to 2000 characters",
 54	      400,
 55	    );
 56	  return { name: normalized, description: description.trim() };
 57	}
 58	export function groupPage(limit: unknown = 50, cursor: unknown = null) {
 59	  const n = Number(limit);
 60	  if (
 61	    !Number.isInteger(n) ||
 62	    n < 1 ||
 63	    n > 100 ||
 64	    (cursor !== null && (typeof cursor !== "string" || cursor.length > 200))
 65	  )
 66	    throw new DomainError("VALIDATION_FAILED", "Invalid group page", 400);
 67	  return { limit: n, cursor };
 68	}
 69	function writePermission(principal: Principal) {
 70	  authorize(principal, "workspace:update");
 71	}
