import { AuthorizationError, DomainError } from "./errors.js";
import type { Principal, ServicePrincipalScope, WorkspaceRole } from "./principal.js";

export const WORKSPACE_ACTIONS = [
  "workspace:read",
  "workspace:update",
  "members:read",
  "members:write",
  "skills:read",
  "skills:write",
  "skills:amend",
  "skills:publish",
  "contexts:read",
  "contexts:write",
  "analytics:read",
  "audit:read",
  "workspace:delete",
] as const;

export type WorkspaceAction = (typeof WORKSPACE_ACTIONS)[number];

const roleActions: Readonly<Record<WorkspaceRole, ReadonlySet<WorkspaceAction>>> = {
  viewer: new Set([
    "workspace:read",
    "members:read",
    "skills:read",
    "contexts:read",
    "analytics:read",
  ]),
  editor: new Set([
