  "skills:amend",
  "skills:publish",
  "contexts:read",
  "contexts:write",
  "analytics:read",
  "audit:read",
  "workspace:delete",
] as const;

export type WorkspaceAction = (typeof WORKSPACE_ACTIONS)[number];

const roleActions: Readonly<Record<WorkspaceRole, ReadonlySet<WorkspaceAction>>> = {
  viewer: new Set([
    "workspace:read",
    "members:read",
    "skills:read",
    "contexts:read",
    "analytics:read",
